import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        Deque<Integer> queue = new ArrayDeque<>();
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < n; i++) {
            String line = br.readLine().trim();
            if (line.startsWith("push")) {
                queue.offerLast(Integer.parseInt(line.split(" ")[1]));
            } else if (line.equals("pop")) {
                sb.append(queue.isEmpty() ? -1 : queue.pollFirst()).append('\n');
            } else if (line.equals("front")) {
                sb.append(queue.isEmpty() ? -1 : queue.peekFirst()).append('\n');
            } else if (line.equals("size")) {
                sb.append(queue.size()).append('\n');
            } else if (line.equals("empty")) {
                sb.append(queue.isEmpty() ? 1 : 0).append('\n');
            }
        }
        System.out.print(sb.toString().trim());
    }
}

#include<iostream>
#include<string>
#include<queue>
using namespace std;
int main(){
    int n; cin>>n; cin.ignore();
    queue<int> q;
    string res="";
    for(int i=0;i<n;i++){
        string line; getline(cin,line);
        if(line.substr(0,4)=="push"){
            q.push(stoi(line.substr(5)));
        } else if(line=="pop"){
            if(q.empty()) res+="-1\n";
            else{res+=to_string(q.front())+"\n";q.pop();}
        } else if(line=="front"){
            if(q.empty()) res+="-1\n";
            else res+=to_string(q.front())+"\n";
        } else if(line=="size"){
            res+=to_string(q.size())+"\n";
        } else if(line=="empty"){
            res+=(q.empty()?string("1"):string("0"))+"\n";
        }
    }
    if(!res.empty()&&res.back()=='\n') res.pop_back();
    cout<<res<<"\n";
}

